   292→        dataSource,
   293→        timestampSpec,
   294→        dimensionsSpec,
   295→        aggregators,
   296→        granularitySpec,
   297→        transformSpec,
   298→        parserMap,
   299→        objectMapper
   300→    );
   301→  }
