   304→  public String toString()
   305→  {
   306→    return "DataSchema{" +
   307→           "dataSource='" + dataSource + '\'' +
   308→           ", aggregators=" + Arrays.toString(aggregators) +
   309→           ", granularitySpec=" + granularitySpec +
   310→           ", transformSpec=" + transformSpec +
   311→           ", parserMap=" + parserMap +
   312→           ", timestampSpec=" + timestampSpec +
