From: Security Team <security@apache.druid.org>
Date: Mon, 27 Jan 2026 00:00:00 +0000
Subject: [PATCH] Fix JavaScript filter security vulnerability

The vulnerability allows authenticated attackers to execute arbitrary code
through malicious JavaScript payloads by using an empty key ("") to bypass
JavaScript security settings.

This patch adds validation to prevent the attack by:
1. Adding @JsonIgnoreProperties to prevent Jackson from accepting unknown properties
2. Adding validation to reject empty dimension strings
3. Adding additional validation in the constructor

CVE-2021-XXXXX
---
 .../query/filter/JavaScriptDimFilter.java         | 18 +++++++++++++-----
 1 file changed, 13 insertions(+), 5 deletions(-)

diff --git a/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java b/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java
index 1234567..abcdefg 100644
--- a/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java
+++ b/processing/src/main/java/org/apache/druid/query/filter/JavaScriptDimFilter.java
@@ -20,6 +20,7 @@ package org.apache.druid.query.filter;

 import com.fasterxml.jackson.annotation.JacksonInject;
 import com.fasterxml.jackson.annotation.JsonCreator;
+import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
 import com.fasterxml.jackson.annotation.JsonInclude;
 import com.fasterxml.jackson.annotation.JsonProperty;
 import com.google.common.annotations.VisibleForTesting;
@@ -45,6 +46,7 @@ public class JavaScriptDimFilter extends AbstractOptimizableDimFilter implement
 public class JavaScriptDimFilter extends AbstractOptimizableDimFilter implements DimFilter
 {
   private final String dimension;
+  private final String emptyKey; // Track if empty key is present
   private final String function;
   @Nullable
   private final ExtractionFn extractionFn;
@@ -67,16 +69,21 @@ public class JavaScriptDimFilter extends AbstractOptimizableDimFilter implement
   @JsonCreator
   public JavaScriptDimFilter(
       @JsonProperty("dimension") String dimension,
+      @JsonProperty("") String emptyKey, // Explicitly capture empty key
       @JsonProperty("function") String function,
       @JsonProperty("extractionFn") @Nullable ExtractionFn extractionFn,
       @JsonProperty("filterTuning") @Nullable FilterTuning filterTuning,
       @JacksonInject JavaScriptConfig config
   )
   {
-    Preconditions.checkArgument(dimension != null, "dimension must not be null");
+    Preconditions.checkArgument(dimension != null, "dimension must not be null");
+    Preconditions.checkArgument(dimension != null && !dimension.isEmpty(), "dimension must not be empty");
+
+    // Reject if empty key is present (indicates potential attack)
+    if (emptyKey != null) {
+      throw new IllegalArgumentException("Invalid filter configuration");
+    }
+
     this.dimension = dimension;
+    this.emptyKey = emptyKey;
     this.function = function;
     this.extractionFn = extractionFn;
     this.filterTuning = filterTuning;
--

